        dx = hull[i][0] - hull[i-1][0]
        dy = hull[i][1] - hull[i-1][1]
        if dx == 0:
            slope = float('inf')
        else:
            slope = dy / dx
        slopes.append(slope)
    return len(set(slopes))

def run_trial(seed):
